text:
Live, interactive demo (Observable JS)
Quarto ships with Observable JS built in — no Python/R kernel required, it runs straight in the browser. Drag the slider:

viewof n = Inputs.range([1, 50], {value: 10, step: 1, label: "n"})







md`**${n} squared is ${n * n}.**`







Plot.plot({
  marks: [
    Plot.barY(
      Array.from({length: n}, (_, i) =&gt; ({x: i + 1, y: (i + 1) ** 2})),
      {x: "x", y: "y", fill: "steelblue"}
    )
  ],
  y: {label: "value²"},
  x: {label: "value"}
})

1.000 personas, un día
Cada punto representa a 1 de cada 1.000 habitantes. Los puntos se agrupan según la actividad que realizan en cada momento del día — igual que en la visualización original, pero con proporciones reales de la ENUT 2021 en vez de simuladas.

overallRaw = FileAttachment("data/enut_ar/oneday_overall.json").json()







overallByTime = {
  const m = new Map();
  for (const t of new Set(overallRaw.map(d =&gt; d.time))) {
    const rows = overallRaw.filter(d =&gt; d.time === t);
    m.set(t, Object.fromEntries(rows.map(r =&gt; [r.grupo, r.n])));
  }
  return m;
}







overallTimes = [...overallByTime.keys()].sort()







// "Traslados" (Traveling) sits at the hub, like the reference visualization
// -- everyone passes through it on their way between other activities.
// The rest are arranged in a ring, with more radius given to the bigger
// categories (Dormir especially, since sleep alone can hold ~950/1000 dots).
centroids = {
  const cx = 550, cy = 380;
  const ring = [
    ["Dormir", 320],
    ["Ocio", 270],
    ["Trabajo", 270],
    ["Domésticas", 270],
    ["Comer y beber", 250],
    ["Cuidado personal", 210],
    ["Educación", 195],
    ["Cuidado", 210],
    ["Voluntarias", 195],
    ["Sin clasificar", 195]
  ];
  const result = {"Traslados": [cx, cy]};
  ring.forEach(([g, r], i) =&gt; {
    const angle = (i / ring.length) * 2 * Math.PI - Math.PI / 2;
    result[g] = [cx + r * Math.cos(angle), cy + r * Math.sin(angle)];
  });
  return result;
}







oneDayViz = {
  const width = 1100, height = 800;
  const colorFor = Object.fromEntries(grupoOrder.map((g, i) =&gt; [g, grupoColors[i]]));

  function formatTime(t) {
    const [h, m] = t.split(":").map(Number);
    const period = h &lt; 12 ? "am" : "pm";
    let h12 = h % 12;
    if (h12 === 0) h12 = 12;
    return `${h12}:${String(m).padStart(2, "0")}${period}`;
  }

  // build the initial 1000 dots from the first time slot's counts
  function buildDots(t) {
    const counts = overallByTime.get(t);
    const dots = [];
    let idx = 0;
    for (const g of grupoOrder) {
      const n = counts[g] || 0;
      const [cx, cy] = centroids[g];
      for (let i = 0; i &lt; n; i++) {
        dots.push({id: idx++, grupo: g, x: cx + (Math.random() - 0.5) * 20, y: cy + (Math.random() - 0.5) * 20});
      }
    }
    return dots;
  }

  let timeIndex = 0;
  const dots = buildDots(overallTimes[0]);

  const container = html`&lt;div&gt;
    &lt;div style="text-align:center; font-size: 2.2rem; color: var(--bs-secondary-color, #666); font-weight: 300;" class="time-label"&gt;&lt;/div&gt;
    &lt;div style="text-align:center; margin-bottom: 10px;"&gt;
      &lt;button class="btn-play" style="padding: 4px 10px; margin-right: 6px;"&gt;⏸ Pausar&lt;/button&gt;
      &lt;button class="btn-slow" style="padding: 4px 10px; margin-right: 6px;"&gt;Lento&lt;/button&gt;
      &lt;button class="btn-fast" style="padding: 4px 10px;"&gt;Rápido&lt;/button&gt;
    &lt;/div&gt;
    &lt;div style="display:flex; gap: 24px; align-items:flex-start; flex-wrap: wrap;"&gt;
      &lt;div class="chart-holder"&gt;&lt;/div&gt;
      &lt;div class="side-panel" style="flex: 1; min-width: 260px;"&gt;
        &lt;div class="bar-holder"&gt;&lt;/div&gt;
      &lt;/div&gt;
    &lt;/div&gt;
  &lt;/div&gt;`;

  const svg = d3.select(container.querySelector(".chart-holder"))
    .append("svg")
    .attr("width", width)
    .attr("height", height)
    .attr("viewBox", [0, 0, width, height])
    .attr("style", "max-width: 100%; height: auto;");

  const pctLabels = {};
  for (const g of grupoOrder) {
    const [cx, cy] = centroids[g];
    svg.append("text")
      .attr("x", cx).attr("y", cy - 46)
      .attr("text-anchor", "middle")
      .attr("font-size", 12)
      .attr("fill", "currentColor")
      .text(g);
    pctLabels[g] = svg.append("text")
      .attr("x", cx).attr("y", cy - 32)
      .attr("text-anchor", "middle")
      .attr("font-size", 11)
      .attr("fill", "currentColor")
      .attr("opacity", 0.7);
  }

  const circles = svg.selectAll("circle")
    .data(dots, d =&gt; d.id)
    .join("circle")
    .attr("r", 2.4)
    .attr("fill", d =&gt; colorFor[d.grupo])
    .attr("cx", d =&gt; d.x)
    .attr("cy", d =&gt; d.y)
    .attr("opacity", 0.85);

  const sim = d3.forceSimulation(dots)
    .force("x", d3.forceX(d =&gt; centroids[d.grupo][0]).strength(0.1))
    .force("y", d3.forceY(d =&gt; centroids[d.grupo][1]).strength(0.1))
    .force("collide", d3.forceCollide(2.6))
    .alphaDecay(0.03)
    .on("tick", () =&gt; {
      circles.attr("cx", d =&gt; d.x).attr("cy", d =&gt; d.y);
    });

  function updateSidePanel(t) {
    const counts = overallByTime.get(t);
    const ranked = grupoOrder.map(g =&gt; ({grupo: g, n: counts[g] || 0})).sort((a, b) =&gt; b.n - a.n);
    const barHolder = container.querySelector(".bar-holder");
    barHolder.innerHTML = "";
    barHolder.appendChild(Plot.plot({
      width: 340,
      height: 420,
      marginLeft: 150,
      x: {label: "personas de 1.000 →", domain: [0, 1000]},
      y: {domain: ranked.map(d =&gt; d.grupo), label: null},
      marks: [
        Plot.barX(ranked, {y: "grupo", x: "n", fill: d =&gt; colorFor[d.grupo]}),
        Plot.text(ranked, {y: "grupo", x: "n", dx: 20, text: d =&gt; d.n, textAnchor: "start"}),
        Plot.ruleX([0])
      ]
    }));
    for (const g of grupoOrder) {
      pctLabels[g].text(Math.round((counts[g] || 0) / 10) + "%");
    }
    container.querySelector(".time-label").textContent = formatTime(t);
  }

  function advance() {
    timeIndex = (timeIndex + 1) % overallTimes.length;
    const t = overallTimes[timeIndex];
    const target = overallByTime.get(t);

    const currentByGrupo = d3.group(dots, d =&gt; d.grupo);
    const pool = [];
    for (const g of grupoOrder) {
      const arr = currentByGrupo.get(g) || [];
      const want = target[g] || 0;
      for (let i = want; i &lt; arr.length; i++) pool.push(arr[i]);
    }
    let poolIdx = 0;
    for (const g of grupoOrder) {
      const arr = currentByGrupo.get(g) || [];
      const want = target[g] || 0;
      for (let i = arr.length; i &lt; want && poolIdx &lt; pool.length; i++, poolIdx++) {
        pool[poolIdx].grupo = g;
      }
    }

    circles.attr("fill", d =&gt; colorFor[d.grupo]);
    // d3-force's forceX/forceY accessors are only evaluated once, at
    // initialization -- re-setting the forces after mutating d.grupo makes
    // d3 recompute each node's target, otherwise dots keep the old target
    // forever even after their category (and color) has changed.
    sim.force("x", d3.forceX(d =&gt; centroids[d.grupo][0]).strength(0.1));
    sim.force("y", d3.forceY(d =&gt; centroids[d.grupo][1]).strength(0.1));
    sim.alpha(0.7).restart();
    updateSidePanel(t);
  }

  let playing = true;
  let speed = 250;
  let timer = setInterval(advance, speed);
  function restartTimer() {
    clearInterval(timer);
    timer = setInterval(advance, speed);
  }

  container.querySelector(".btn-play").onclick = (e) =&gt; {
    playing = !playing;
    e.target.textContent = playing ? "⏸ Pausar" : "▶ Reanudar";
    if (playing) restartTimer(); else clearInterval(timer);
  };
  container.querySelector(".btn-slow").onclick = () =&gt; { speed = 600; if (playing) restartTimer(); };
  container.querySelector(".btn-fast").onclick = () =&gt; { speed = 100; if (playing) restartTimer(); };

  invalidation.then(() =&gt; clearInterval(timer));

  updateSidePanel(overallTimes[0]);

  return container;
}












Note



Los 1.000 puntos son una muestra proporcional reconstruida a partir de los porcentajes reales por intervalo de 10 minutos — igual que en la visualización original, no son 1.000 personas reales rastreadas individualmente. En cada paso, solo se mueven los puntos que necesitan cambiar de categoría para que el total vuelva a cuadrar con los datos.

El mismo patrón, desagregado por sexo

// Stack manually (y0/y1 per time+sex, in grupoOrder) instead of relying on
// Plot's automatic stack transform -- more predictable and easier to verify.
stacked = {
  const byKey = d3.group(oneDay, d =&gt; `${d.time}|${d.sex}`);
  const rows = [];
  for (const arr of byKey.values()) {
    const base = arr[0];
    let y0 = 0;
    for (const g of grupoOrder) {
      const rec = arr.find(r =&gt; r.grupo === g);
      const pct = rec ? rec.pct : 0;
      const y1 = y0 + pct;
      rows.push({time: base.time, hour: base.hour, sex: base.sex, grupo: g, pct, y0, y1});
      y0 = y1;
    }
  }
  return rows;
}







stackedMujeres = stacked.filter(d =&gt; d.sex === "Mujeres")
stackedVarones = stacked.filter(d =&gt; d.sex === "Varones")
















// Two separate plots (not one faceted with fy:"sex") -- Plot.areaY with
// explicit y1/y2 channels renders incorrectly when combined with fy
// faceting in the Plot version bundled here; two plain plots sidestep it.
dayChart = (data, title) =&gt; Plot.plot({
  title,
  width: 800,
  height: 260,
  marginLeft: 50,
  x: {label: "Hora del día →", domain: [0, 24], ticks: [0, 3, 6, 9, 12, 15, 18, 21, 24], tickFormat: d =&gt; `${d}h`},
  y: {label: "Proporción de la población →", domain: [0, 1], tickFormat: d =&gt; `${Math.round(d * 100)}%`},
  color: {legend: true, domain: grupoOrder, range: grupoColors},
  marks: [
    Plot.areaY(data, {x: "hour", y1: "y0", y2: "y1", fill: "grupo", tip: true}),
    Plot.ruleY([0])
  ]
})







dayChart(stackedMujeres, "Mujeres")







dayChart(stackedVarones, "Varones")












Important



El patrón de sueño (“Dormir”, que domina la madrugada) es casi idéntico entre mujeres y varones. La diferencia salta a la vista durante el día: los varones muestran un pico de “Trabajo” más pronunciado al mediodía, mientras que “Domésticas” y “Cuidado” ocupan una porción visiblemente mayor del día de las mujeres, sin que su “Trabajo” remunerado disminuya tanto durante esas horas — el patrón visual de la doble jornada.

Segunda vuelta del juego, con otra mecánica: esta vez adivinas una diferencia en puntos porcentuales — cuántos puntos más (o menos) de mujeres, comparado con hombres, realizaron cada tarea doméstica en un día típico — moviendo la aguja de un medidor. Ojo: en algunas tareas son los hombres quienes participan más, así que la aguja puede apuntar hacia cualquiera de los dos lados.
participationRaw = FileAttachment("data/enut/clock_participation.json").json()
colorH = "#5c9e95"
colorM = "#c7a3c0"
accentColor = "#c26b5a"
activityIcons = ({
  psc: "🍲", lv: "🧹", lrc: "🧺", mrm: "🔧", admnhog: "🧾", comphog: "🛒", cmp: "🐾"
})
function shuffle(arr) {
  const a = arr.slice();
  for (let i = a.length - 1; i &gt; 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}
activityList = [...new Set(participationRaw.map(d =&gt; d.activity_code))].map(code =&gt; {
  const rec = participationRaw.find(d =&gt; d.activity_code === code && d.age_tab === "Total");
  return { code, label: rec.activity };
})
function getShare(code, sex) {
  const rec = participationRaw.find(d =&gt; d.activity_code === code && d.age_tab === "Total" && d.sex === sex);
  return rec ? rec.share : null;
}
function roundData(code) {
  const shareM = getShare(code, "Mujeres");
  const shareH = getShare(code, "Hombres");
  const gap = Math.round((shareM - shareH) * 100);
  return { code, label: activityList.find(a =&gt; a.code === code).label, shareM, shareH, gap };
}
function feedback(errorAbs) {
  if (errorAbs &lt;= 3) return { emoji: "🎯", text: "¡Exacto!" };
  if (errorAbs &lt;= 8) return { emoji: "🔥", text: "Caliente." };
  if (errorAbs &lt;= 15) return { emoji: "🌤️", text: "Tibio." };
  return { emoji: "🥶", text: "Frío — bastante lejos." };
}
function fmtPP(v) {
  const r = Math.round(v);
  return (r &gt; 0 ? "+" : "") + r + " pp";
}
gaugeGame = {
  const GMIN = -30, GMAX = 30;
  const R = 140, width = 2 * R + 60, height = R + 90;
  const cx = width / 2, cy = height - 55;

  function angleFor(v) {
    const t = Math.max(GMIN, Math.min(GMAX, v));
    return ((t - GMIN) / (GMAX - GMIN) - 0.5) * Math.PI;
  }
  function needlePoint(angle, len) {
    return [cx + Math.sin(angle) * len, cy - Math.cos(angle) * len];
  }

  const wrapper = html`&lt;div&gt;&lt;/div&gt;`;
  const roundBox = html`&lt;div&gt;&lt;/div&gt;`;
  wrapper.appendChild(roundBox);

  let order = shuffle(activityList.map(a =&gt; a.code));
  let roundIndex = 0;
  let results = [];

  function drawGaugeBase(svg) {
    const arcGen = (a0, a1, r0, r1) =&gt; d3.arc().innerRadius(r0).outerRadius(r1).startAngle(a0).endAngle(a1)();
    const g = svg.append("g").attr("transform", `translate(${cx},${cy})`);
    g.append("path").attr("d", arcGen(-Math.PI / 2, 0, R - 16, R)).attr("fill", colorH).attr("opacity", 0.3);
    g.append("path").attr("d", arcGen(0, Math.PI / 2, R - 16, R)).attr("fill", colorM).attr("opacity", 0.3);
    g.append("path").attr("d", arcGen(-Math.PI / 2, Math.PI / 2, R - 16, R)).attr("fill", "none").attr("stroke", "#999").attr("stroke-width", 1);
    // zero tick
    const [zx1, zy1] = [0, -(R - 16)];
    const [zx2, zy2] = [0, -R];
    g.append("line").attr("x1", zx1).attr("y1", zy1).attr("x2", zx2).attr("y2", zy2).attr("stroke", "#666").attr("stroke-width", 2);
    [GMIN, GMIN / 2, 0, GMAX / 2, GMAX].forEach(v =&gt; {
      const a = angleFor(v);
      const [tx, ty] = needlePoint(a, R + 14);
      g.append("text").attr("x", tx - cx).attr("y", ty - cy).attr("text-anchor", "middle").attr("font-size", 10).attr("fill", "currentColor").text(v &gt; 0 ? `+${v}` : `${v}`);
    });
    g.append("text").attr("x", -R - 10).attr("y", 14).attr("text-anchor", "start").attr("font-size", 11).attr("fill", colorH).text("← Hombres");
    g.append("text").attr("x", R + 10).attr("y", 14).attr("text-anchor", "end").attr("font-size", 11).attr("fill", colorM).text("Mujeres →");
    return g;
  }

  function renderRound() {
    roundBox.innerHTML = "";
    const code = order[roundIndex];
    const data = roundData(code);

    const card = html`&lt;div style="max-width: 640px; margin: 0 auto; padding: 24px; border-radius: 10px; background: color-mix(in srgb, currentColor 5%, transparent); text-align:center;"&gt;&lt;/div&gt;`;

    const progress = html`&lt;div style="font-size: 0.85rem; color: var(--bs-secondary-color, #666); margin-bottom: 4px;"&gt;Ronda ${roundIndex + 1} de ${order.length}&lt;/div&gt;`;
    const iconLine = html`&lt;div style="font-size: 2.2rem;"&gt;${activityIcons[code] || "•"}&lt;/div&gt;`;
    const group = html`&lt;div style="font-weight: 700; font-size: 1.1rem; margin-bottom: 8px;"&gt;${data.label}&lt;/div&gt;`;
    const question = html`&lt;div style="margin-bottom: 12px; max-width: 480px; margin-left:auto; margin-right:auto;"&gt;¿Cuántos &lt;strong&gt;puntos porcentuales más&lt;/strong&gt; (o menos) de &lt;span style="color:${colorM}; font-weight:700;"&gt;mujeres&lt;/span&gt;, comparado con &lt;span style="color:${colorH}; font-weight:700;"&gt;hombres&lt;/span&gt;, realizaron esta tarea en un día típico? Mueve la aguja.&lt;/div&gt;`;

    const gaugeHolder = html`&lt;div&gt;&lt;/div&gt;`;
    const svg = d3.select(gaugeHolder).append("svg").attr("width", width).attr("height", height).attr("viewBox", `0 0 ${width} ${height}`).style("max-width", "100%");
    const g = drawGaugeBase(svg);
    const needle = g.append("line").attr("x1", 0).attr("y1", 0).attr("x2", 0).attr("y2", -(R - 24)).attr("stroke", "#333").attr("stroke-width", 3).attr("stroke-linecap", "round");
    g.append("circle").attr("r", 5).attr("fill", "#333");
    const readout = svg.append("text").attr("x", cx).attr("y", cy - R * 0.45).attr("text-anchor", "middle").attr("font-size", 22).attr("font-weight", 700).attr("fill", "currentColor").text("0 pp");

    let guessVal = 0;
    function setNeedle(v) {
      const a = angleFor(v);
      const [nx, ny] = needlePoint(a, R - 24);
      needle.attr("x2", nx - cx).attr("y2", ny - cy);
      readout.text(fmtPP(v));
    }
    setNeedle(0);

    const slider = html`&lt;input type="range" min="${GMIN}" max="${GMAX}" step="1" value="0" style="width: 100%; max-width: 420px;"&gt;`;
    slider.oninput = () =&gt; { guessVal = +slider.value; setNeedle(guessVal); };

    const submitBtn = html`&lt;button style="padding:8px 20px;border-radius:4px;border:1px solid #5c9e95;background:#5c9e95;color:white;cursor:pointer;font-size:0.95rem;margin-top: 16px;"&gt;Comprobar&lt;/button&gt;`;

    card.appendChild(progress);
    card.appendChild(iconLine);
    card.appendChild(group);
    card.appendChild(question);
    card.appendChild(gaugeHolder);
    card.appendChild(slider);
    card.appendChild(document.createElement("br"));
    card.appendChild(submitBtn);
    roundBox.appendChild(card);

    submitBtn.onclick = () =&gt; {
      results.push({ code, label: data.label, guess: guessVal, actual: data.gap, shareM: data.shareM, shareH: data.shareH });
      renderReveal(data, guessVal, g, needle, readout);
    };
  }

  function renderReveal(data, guess, g, needle, readout) {
    const card = roundBox.querySelector("div");
    // disable slider/button, add real needle + feedback
    const slider = card.querySelector('input[type="range"]');
    const submitBtn = card.querySelector("button");
    if (slider) slider.disabled = true;
    submitBtn.remove();

    const errorAbs = Math.abs(guess - data.gap);
    const fb = feedback(errorAbs);
    const fbBox = html`&lt;div style="font-size: 1.05rem; margin: 12px 0;"&gt;&lt;span style="font-size:1.4rem;"&gt;${fb.emoji}&lt;/span&gt; ${fb.text} Adivinaste &lt;strong&gt;${fmtPP(guess)}&lt;/strong&gt;, el valor real es &lt;strong&gt;${fmtPP(data.gap)}&lt;/strong&gt; (te desviaste por ${errorAbs} pp).&lt;/div&gt;`;

    // grey out guess needle, animate a new accent needle to the real value
    needle.attr("stroke", "#aaa").attr("stroke-width", 2).attr("stroke-dasharray", "3,2");
    readout.attr("fill", "#aaa");

    function angleFor(v) {
      const GMIN = -30, GMAX = 30;
      return ((v - GMIN) / (GMAX - GMIN) - 0.5) * Math.PI;
    }
    const R = 140;
    function needlePointLocal(angle, len) {
      return [Math.sin(angle) * len, -Math.cos(angle) * len];
    }
    const realNeedle = g.append("line").attr("x1", 0).attr("y1", 0)
      .attr("x2", 0).attr("y2", -(R - 24))
      .attr("stroke", accentColor).attr("stroke-width", 3.5).attr("stroke-linecap", "round");
    g.append("circle").attr("r", 4).attr("fill", accentColor);

    realNeedle.transition().duration(700).attrTween("x2", () =&gt; {
      const interp = d3.interpolateNumber(angleFor(guess), angleFor(data.gap));
      return t =&gt; needlePointLocal(interp(t), R - 24)[0];
    }).attrTween("y2", () =&gt; {
      const interp = d3.interpolateNumber(angleFor(guess), angleFor(data.gap));
      return t =&gt; needlePointLocal(interp(t), R - 24)[1];
    });

    // context bars
    const barsHolder = html`&lt;div style="margin-top: 16px; text-align:left; max-width: 420px; margin-left:auto; margin-right:auto;"&gt;&lt;/div&gt;`;
    const barsSvg = d3.select(barsHolder).append("svg").attr("width", 420).attr("height", 80).attr("viewBox", "0 0 420 80");
    const rows = [
      { label: "Mujeres", share: data.shareM, color: colorM, y: 8 },
      { label: "Hombres", share: data.shareH, color: colorH, y: 44 }
    ];
    rows.forEach(r =&gt; {
      barsSvg.append("text").attr("x", 0).attr("y", r.y + 15).attr("font-size", 12).attr("fill", "currentColor").text(r.label);
      barsSvg.append("rect").attr("x", 80).attr("y", r.y).attr("width", 4).attr("height", 22).attr("fill", "#ddd");
      barsSvg.append("rect").attr("x", 80).attr("y", r.y).attr("width", r.share * 260).attr("height", 22).attr("fill", r.color).attr("rx", 3);
      barsSvg.append("text").attr("x", 86 + r.share * 260).attr("y", r.y + 15).attr("font-size", 12).attr("fill", "currentColor").text(`${Math.round(r.share * 100)}%`);
    });

    const nextBtn = html`&lt;button style="padding:8px 20px;border-radius:4px;border:1px solid #5c9e95;background:#5c9e95;color:white;cursor:pointer;font-size:0.95rem;margin-top:16px;"&gt;${roundIndex + 1 &lt; order.length ? "Siguiente ronda →" : "Ver resultado final"}&lt;/button&gt;`;
    nextBtn.onclick = () =&gt; {
      if (roundIndex + 1 &lt; order.length) {
        roundIndex += 1;
        renderRound();
      } else {
        renderSummary();
      }
    };

    card.appendChild(fbBox);
    card.appendChild(barsHolder);
    card.appendChild(nextBtn);
  }

  function renderSummary() {
    roundBox.innerHTML = "";
    const card = html`&lt;div style="max-width: 640px; margin: 0 auto; padding: 24px; border-radius: 10px; background: color-mix(in srgb, currentColor 5%, transparent);"&gt;&lt;/div&gt;`;

    const title = html`&lt;div style="font-weight: 700; font-size: 1.2rem; margin-bottom: 16px;"&gt;Resultado final&lt;/div&gt;`;

    const table = html`&lt;table style="width:100%; border-collapse: collapse; margin-bottom: 16px;"&gt;&lt;/table&gt;`;
    const thead = html`&lt;thead&gt;&lt;tr&gt;
      &lt;th style="text-align:left; padding:6px; border-bottom: 1px solid #999;"&gt;Tarea&lt;/th&gt;
      &lt;th style="text-align:right; padding:6px; border-bottom: 1px solid #999;"&gt;Tu respuesta&lt;/th&gt;
      &lt;th style="text-align:right; padding:6px; border-bottom: 1px solid #999;"&gt;Real&lt;/th&gt;
      &lt;th style="text-align:right; padding:6px; border-bottom: 1px solid #999;"&gt;Diferencia&lt;/th&gt;
    &lt;/tr&gt;&lt;/thead&gt;`;
    table.appendChild(thead);
    const tbody = html`&lt;tbody&gt;&lt;/tbody&gt;`;
    let totalError = 0;
    results.forEach(r =&gt; {
      const err = Math.abs(r.guess - r.actual);
      totalError += err;
      const row = html`&lt;tr&gt;
        &lt;td style="padding:6px; border-bottom: 1px solid #eee;"&gt;${activityIcons[r.code] || ""} ${r.label}&lt;/td&gt;
        &lt;td style="text-align:right; padding:6px; border-bottom: 1px solid #eee;"&gt;${fmtPP(r.guess)}&lt;/td&gt;
        &lt;td style="text-align:right; padding:6px; border-bottom: 1px solid #eee;"&gt;${fmtPP(r.actual)}&lt;/td&gt;
        &lt;td style="text-align:right; padding:6px; border-bottom: 1px solid #eee;"&gt;${err} pp&lt;/td&gt;
      &lt;/tr&gt;`;
      tbody.appendChild(row);
    });
    table.appendChild(tbody);

    const avgError = Math.round((totalError / results.length) * 10) / 10;
    const closing = html`&lt;div style="margin-bottom: 20px;"&gt;Tu error promedio fue de &lt;strong&gt;${avgError} pp&lt;/strong&gt; por ronda. ${avgError &lt;= 5 ? "Excelente calibración." : avgError &lt;= 12 ? "Una intuición razonable, aunque algunas tareas sorprenden." : "La brecha real varía más de lo que la mayoría intuye, tarea por tarea."}&lt;/div&gt;`;

    const replayBtn = html`&lt;button style="padding:8px 20px;border-radius:4px;border:1px solid #5c9e95;background:#5c9e95;color:white;cursor:pointer;font-size:0.95rem;"&gt;Jugar de nuevo&lt;/button&gt;`;
    replayBtn.onclick = () =&gt; {
      order = shuffle(activityList.map(a =&gt; a.code));
      roundIndex = 0;
      results = [];
      renderRound();
    };

    card.appendChild(title);
    card.appendChild(table);
    card.appendChild(closing);
    card.appendChild(replayBtn);
    roundBox.appendChild(card);
  }

  renderRound();
  return wrapper;
}

