  const row = html`&lt;div style="display:flex; gap: 40px; justify-content:center; align-items:flex-end; margin-bottom: 12px;"&gt;&lt;/div&gt;`;

  function verticalSlider(label, color) {
    const col = html`&lt;div style="display:flex; flex-direction:column; align-items:center; gap:6px;"&gt;&lt;/div&gt;`;
    const valLabel = html`&lt;div style="font-weight:700; color:${color};"&gt;50%&lt;/div&gt;`;
    const slider = html`&lt;input type="range" min="0" max="100" step="1" value="50"&gt;`;
    slider.style.cssText = `-webkit-appearance: slider-vertical; width: 32px; height: 160px; accent-color: ${color};`;
    const nameLabel = html`&lt;div&gt;${label}&lt;/div&gt;`;
    col.appendChild(valLabel);
    col.appendChild(slider);
    col.appendChild(nameLabel);
    return { col, slider, valLabel };
  }

  const mCol = verticalSlider("Mujeres", colorM);
  const hCol = verticalSlider("Hombres", colorH);
  row.appendChild(mCol.col);
  row.appendChild(hCol.col);

  const gapReadout = html`&lt;div style="font-size: 1.05rem; margin-bottom: 12px;"&gt;Brecha implícita: &lt;strong&gt;0 pp&lt;/strong&gt;&lt;/div&gt;`;
  function updateGapReadout() {
    const g = (+mCol.slider.value) - (+hCol.slider.value);
    gapReadout.querySelector("strong").textContent = fmtPP(g);
  }
  mCol.slider.oninput = () =&gt; { mCol.valLabel.textContent = mCol.slider.value + "%"; updateGapReadout(); };
  hCol.slider.oninput = () =&gt; { hCol.valLabel.textContent = hCol.slider.value + "%"; updateGapReadout(); };

  const submitBtn = html`&lt;button style="padding:8px 20px;border-radius:4px;border:1px solid #5c9e95;background:#5c9e95;color:white;cursor:pointer;font-size:0.95rem;margin-top:8px;"&gt;Comprobar&lt;/button&gt;`;

  card.appendChild(iconLine);
  card.appendChild(group);
  card.appendChild(question);
  card.appendChild(row);
  card.appendChild(gapReadout);
  card.appendChild(submitBtn);
  container.appendChild(card);

  submitBtn.onclick = () =&gt; {
    mCol.slider.disabled = true;
    hCol.slider.disabled = true;
    submitBtn.remove();
    const guessM = +mCol.slider.value, guessH = +hCol.slider.value;
    const guessGap = guessM - guessH;
    const errorAbs = Math.abs(guessGap - data.gap);
