    const fbBox = html`&lt;div style="font-size: 1.05rem; margin: 12px 0;"&gt;&lt;span style="font-size:1.4rem;"&gt;${fb.emoji}&lt;/span&gt; ${fb.text} Tu combinación implica &lt;strong&gt;${fmtPP(guessGap)}&lt;/strong&gt;, la brecha real es &lt;strong&gt;${fmtPP(data.gap)}&lt;/strong&gt; (te desviaste por ${errorAbs} pp).&lt;/div&gt;`;
    const bars = contextBarsSvg(data.shareM, data.shareH);
    card.appendChild(fbBox);
    card.appendChild(bars);
    card.appendChild(retryButton(container, buildThermoDemo));
  };
}







