  const templates = [
    { id: "line", label: "Línea numérica", build: buildLineDemo },
    { id: "seesaw", label: "Balanza", build: buildSeesawDemo },
    { id: "thermo", label: "Termómetros", build: buildThermoDemo }
  ];

  let active = "line";
  const buttons = templates.map(t =&gt; {
    const b = document.createElement("button");
    b.textContent = t.label;
    b.style.cssText = "padding:6px 16px;margin:0 4px 8px;border-radius:4px;border:1px solid #5c9e95;cursor:pointer;font-size:0.9rem;";
    b.onclick = () =&gt; { active = t.id; refresh(); };
    tabBar.appendChild(b);
    return { btn: b, id: t.id };
  });

  function updateButtons() {
    buttons.forEach(({ btn, id }) =&gt; {
      const on = id === active;
      btn.style.background = on ? "#5c9e95" : "white";
      btn.style.color = on ? "white" : "#333";
    });
  }

  function refresh() {
    updateButtons();
    demoBox.innerHTML = "";
    templates.find(t =&gt; t.id === active).build(demoBox);
  }

  refresh();
  return wrapper;
}

La página Cuidado remunerado muestra estos datos con barras verticales y un facet por definición. Aquí exploramos cinco formas distintas de mirar exactamente la misma información — todas horizontales, para que las dos dimensiones del dato (definiciones anidadas y categorías individuales) compartan un mismo eje y se puedan comparar directamente entre sí.
