// share for each sex has its OWN denominator (see the callout above --
// svyby computes the mean within each sex separately), so a single shared
// 100-square grid mixing both would misrepresent them as slices of one
// population. Instead: two independent 100-square grids per category, one
// for "100 hombres ocupados", one for "100 mujeres ocupadas" -- each
// filled with its own share, in its own color, grey for the rest of that
// same sex's occupied population.
function waffleSquares(share, color) {
  const n = Math.round(share * 100);
  return Array.from({ length: 100 }, (_, i) =&gt; ({
    col: i % 10,
    row: Math.floor(i / 10),
    fill: i &lt; n ? color : "#e2e2e2",
    filled: i &lt; n
  }));
}

function waffleGrid(share, color, sexLabel, category) {
  const cell = 10, gap = 2, side = cell * 10 + gap * 9;
  const squares = waffleSquares(share, color);
  const svg = d3.create("svg").attr("width", side).attr("height", side);
  svg.selectAll("rect").data(squares).join("rect")
    .attr("x", d =&gt; d.col * (cell + gap))
    .attr("y", d =&gt; d.row * (cell + gap))
    .attr("width", cell).attr("height", cell)
    .attr("rx", 2)
    .attr("fill", d =&gt; d.fill)
    .append("title").text(d =&gt; `${category}\n${d.filled ? sexLabel : `resto de ${sexLabel.toLowerCase()} ocupados/as`}`);
  return svg.node();
}

function wafflePanel(data, order) {
  const legend = html`&lt;div style="display:flex; gap:16px; margin-bottom:16px; font-size:12px; align-items:center; flex-wrap:wrap;"&gt;&lt;/div&gt;`;
  [["Hombres", colorH], ["Mujeres", colorM], ["Resto de ocupados/as del mismo sexo", "#e2e2e2"]].forEach(([label, color]) =&gt; {
    const item = html`&lt;div style="display:flex; align-items:center; gap:6px;"&gt;&lt;/div&gt;`;
    item.appendChild(html`&lt;span style="display:inline-block; width:12px; height:12px; border-radius:2px; background:${color};"&gt;&lt;/span&gt;`);
    item.appendChild(html`&lt;span&gt;${label}&lt;/span&gt;`);
    legend.appendChild(item);
  });

  const grid = html`&lt;div style="display:flex; flex-wrap:wrap; gap:28px;"&gt;&lt;/div&gt;`;
  order.forEach(category =&gt; {
    const shareH = data.find(d =&gt; d.category === category && d.sex === "Hombres")?.share ?? 0;
    const shareM = data.find(d =&gt; d.category === category && d.sex === "Mujeres")?.share ?? 0;

    const pair = html`&lt;div style="display:flex; gap:10px;"&gt;&lt;/div&gt;`;
    const hCol = html`&lt;div style="display:flex; flex-direction:column; align-items:center; gap:4px;"&gt;&lt;/div&gt;`;
    hCol.appendChild(waffleGrid(shareH, colorH, "Hombres", category));
    hCol.appendChild(html`&lt;div style="font-size:11px;"&gt;${(shareH * 100).toFixed(1)}% H&lt;/div&gt;`);
    const mCol = html`&lt;div style="display:flex; flex-direction:column; align-items:center; gap:4px;"&gt;&lt;/div&gt;`;
    mCol.appendChild(waffleGrid(shareM, colorM, "Mujeres", category));
    mCol.appendChild(html`&lt;div style="font-size:11px;"&gt;${(shareM * 100).toFixed(1)}% M&lt;/div&gt;`);
    pair.appendChild(hCol);
    pair.appendChild(mCol);

    const col = html`&lt;div style="display:flex; flex-direction:column; align-items:center; gap:8px; max-width:280px;"&gt;&lt;/div&gt;`;
    col.appendChild(pair);
    col.appendChild(html`&lt;div style="font-size:12px; text-align:center;"&gt;${category}&lt;/div&gt;`);
    grid.appendChild(col);
  });

  const wrapper = html`&lt;div&gt;&lt;/div&gt;`;
  wrapper.appendChild(legend);
  wrapper.appendChild(grid);
  return wrapper;
}

function panel(data, order, width) {
  if (chartStyle === "Barras divergentes") return divergingPanel(data, order, width);
  if (chartStyle === "Razón mujeres/hombres") return ratioPanel(data, order, width);
  if (chartStyle === "Mapa de calor") return heatmapPanel(data, order, width);
  if (chartStyle === "Waffle") return wafflePanel(data, order);
  return groupedBarPanel(data, order, width);
}

