    const progress = html`&lt;div style="font-size: 0.85rem; color: var(--bs-secondary-color, #666); margin-bottom: 4px;"&gt;Ronda ${roundIndex + 1} de ${order.length}&lt;/div&gt;`;
    const group = html`&lt;div style="font-weight: 700; font-size: 1.1rem; margin-bottom: 12px;"&gt;${ageTabLabel[data.ageTab]}&lt;/div&gt;`;

    const errorAbs = Math.abs(guess - data.gapMin);
    const fb = feedback(errorAbs, data.gapMin);
    const fbBox = html`&lt;div style="font-size: 1.05rem; margin-bottom: 16px;"&gt;&lt;span style="font-size:1.4rem;"&gt;${fb.emoji}&lt;/span&gt; ${fb.text} Adivinaste &lt;strong&gt;${formatMin(guess)}&lt;/strong&gt;, la brecha real es &lt;strong&gt;${formatMin(data.gapMin)}&lt;/strong&gt; (te desviaste por ${formatMin(errorAbs)}).&lt;/div&gt;`;

    // number line comparing guess vs actual
    const niceMax = Math.max(50, Math.ceil((Math.max(guess, data.gapMin) * 1.3) / 10) * 10);
    const svgWidth = 600, svgHeight = 100, x0 = 30, x1 = svgWidth - 30;
    const scale = v =&gt; x0 + (v / niceMax) * (x1 - x0);

    const lineHolder = html`&lt;div style="overflow-x:auto;"&gt;&lt;/div&gt;`;
    const svg = d3.select(lineHolder).append("svg").attr("width", svgWidth).attr("height", svgHeight).attr("viewBox", `0 0 ${svgWidth} ${svgHeight}`);

    svg.append("line").attr("x1", x0).attr("x2", x1).attr("y1", 60).attr("y2", 60).attr("stroke", "#999").attr("stroke-width", 1.5);
    const nTicks = 5;
    for (let i = 0; i &lt;= nTicks; i++) {
      const v = Math.round((niceMax / nTicks) * i);
      const x = scale(v);
      svg.append("line").attr("x1", x).attr("x2", x).attr("y1", 56).attr("y2", 64).attr("stroke", "#999");
      svg.append("text").attr("x", x).attr("y", 78).attr("text-anchor", "middle").attr("font-size", 10).attr("fill", "currentColor").text(formatMin(v));
    }

    const gx = scale(guess);
    svg.append("line").attr("x1", gx).attr("x2", gx).attr("y1", 30).attr("y2", 60).attr("stroke", "#888").attr("stroke-width", 2).attr("stroke-dasharray", "3,2");
    svg.append("circle").attr("cx", gx).attr("cy", 30).attr("r", 4).attr("fill", "#888");
    svg.append("text").attr("x", gx).attr("y", 20).attr("text-anchor", "middle").attr("font-size", 11).attr("fill", "#888").text("Tu respuesta");

    const ax = scale(data.gapMin);
    svg.append("line").attr("x1", ax).attr("x2", ax).attr("y1", 30).attr("y2", 60).attr("stroke", accentColor).attr("stroke-width", 2.5);
    svg.append("circle").attr("cx", ax).attr("cy", 60).attr("r", 5).attr("fill", accentColor);
    svg.append("text").attr("x", ax).attr("y", 20).attr("text-anchor", "middle").attr("font-size", 11).attr("fill", accentColor).attr("font-weight", 700).text("Real");

    // context bars: hours by sex
    const barsHolder = html`&lt;div style="margin-top: 20px;"&gt;&lt;/div&gt;`;
    const barsSvg = d3.select(barsHolder).append("svg").attr("width", svgWidth).attr("height", 90).attr("viewBox", `0 0 ${svgWidth} 90`);
    const maxHours = Math.max(data.hoursM, data.hoursH) * 1.15;
    const barScale = h =&gt; (h / maxHours) * (svgWidth - 140);
    const rows = [
      { label: "Mujeres", hours: data.hoursM, color: colorM, y: 10 },
      { label: "Hombres", hours: data.hoursH, color: colorH, y: 50 }
    ];
    rows.forEach(r =&gt; {
      barsSvg.append("text").attr("x", 0).attr("y", r.y + 15).attr("font-size", 12).attr("fill", "currentColor").text(r.label);
      barsSvg.append("rect").attr("x", 90).attr("y", r.y).attr("width", barScale(r.hours)).attr("height", 22).attr("fill", r.color).attr("rx", 3);
      const hh = Math.floor(r.hours);
      const mm = Math.round((r.hours - hh) * 60);
      barsSvg.append("text").attr("x", 96 + barScale(r.hours)).attr("y", r.y + 15).attr("font-size", 12).attr("fill", "currentColor").text(`${hh} h ${mm} min`);
    });

    const nextBtn = html`&lt;button style="padding:8px 20px;border-radius:4px;border:1px solid #5c9e95;background:#5c9e95;color:white;cursor:pointer;font-size:0.95rem;margin-top:20px;"&gt;${roundIndex + 1 &lt; order.length ? "Siguiente ronda →" : "Ver resultado final"}&lt;/button&gt;`;
    nextBtn.onclick = () =&gt; {
      if (roundIndex + 1 &lt; order.length) {
        roundIndex += 1;
        renderRound();
      } else {
        renderSummary();
      }
    };

    card.appendChild(progress);
    card.appendChild(group);
    card.appendChild(fbBox);
    card.appendChild(lineHolder);
    card.appendChild(barsHolder);
    card.appendChild(nextBtn);
    roundBox.appendChild(card);
  }

  function renderSummary() {
    roundBox.innerHTML = "";
    const card = html`&lt;div style="max-width: 640px; margin: 0 auto; padding: 24px; border-radius: 10px; background: color-mix(in srgb, currentColor 5%, transparent);"&gt;&lt;/div&gt;`;

    const title = html`&lt;div style="font-weight: 700; font-size: 1.2rem; margin-bottom: 16px;"&gt;Resultado final&lt;/div&gt;`;

    const table = html`&lt;table style="width:100%; border-collapse: collapse; margin-bottom: 16px;"&gt;&lt;/table&gt;`;
    const thead = html`&lt;thead&gt;&lt;tr&gt;
      &lt;th style="text-align:left; padding:6px; border-bottom: 1px solid #999;"&gt;Grupo&lt;/th&gt;
      &lt;th style="text-align:right; padding:6px; border-bottom: 1px solid #999;"&gt;Tu respuesta&lt;/th&gt;
      &lt;th style="text-align:right; padding:6px; border-bottom: 1px solid #999;"&gt;Real&lt;/th&gt;
      &lt;th style="text-align:right; padding:6px; border-bottom: 1px solid #999;"&gt;Diferencia&lt;/th&gt;
    &lt;/tr&gt;&lt;/thead&gt;`;
    table.appendChild(thead);
    const tbody = html`&lt;tbody&gt;&lt;/tbody&gt;`;
    let totalError = 0;
    results.forEach(r =&gt; {
      const err = Math.abs(r.guess - r.actual);
      totalError += err;
      const row = html`&lt;tr&gt;
        &lt;td style="padding:6px; border-bottom: 1px solid #eee;"&gt;${ageTabLabel[r.ageTab]}&lt;/td&gt;
        &lt;td style="text-align:right; padding:6px; border-bottom: 1px solid #eee;"&gt;${formatMin(r.guess)}&lt;/td&gt;
        &lt;td style="text-align:right; padding:6px; border-bottom: 1px solid #eee;"&gt;${formatMin(r.actual)}&lt;/td&gt;
        &lt;td style="text-align:right; padding:6px; border-bottom: 1px solid #eee;"&gt;${formatMin(err)}&lt;/td&gt;
      &lt;/tr&gt;`;
      tbody.appendChild(row);
    });
    table.appendChild(tbody);

    const avgError = Math.round(totalError / results.length);
    const closing = html`&lt;div style="margin-bottom: 20px;"&gt;Tu error promedio fue de &lt;strong&gt;${formatMin(avgError)}&lt;/strong&gt; por ronda. ${avgError &lt;= 15 ? "Muy buena intuición sobre la brecha de género en el trabajo doméstico." : avgError &lt;= 35 ? "Una intuición razonable, aunque la brecha real suele ser más marcada de lo que se piensa." : "La brecha real es más grande de lo que la mayoría intuye — así es la desigualdad en el trabajo doméstico no remunerado."}&lt;/div&gt;`;

    const replayBtn = html`&lt;button style="padding:8px 20px;border-radius:4px;border:1px solid #5c9e95;background:#5c9e95;color:white;cursor:pointer;font-size:0.95rem;"&gt;Jugar de nuevo&lt;/button&gt;`;
    replayBtn.onclick = () =&gt; {
      order = shuffle(ageTabOrder);
      roundIndex = 0;
      results = [];
      renderRound();
    };

    card.appendChild(title);
    card.appendChild(table);
    card.appendChild(closing);
    card.appendChild(replayBtn);
    roundBox.appendChild(card);
  }

  renderRound();
  return wrapper;
}

