  function updateGapReadout() {
    const g = (+mCol.slider.value) - (+hCol.slider.value);
    gapReadout.querySelector("strong").textContent = g &gt;= 0 ? `${formatMin(g)} más` : `${formatMin(-g)} menos`;
  }
  mCol.slider.oninput = () =&gt; { mCol.valLabel.textContent = formatMin(+mCol.slider.value); updateGapReadout(); };
  hCol.slider.oninput = () =&gt; { hCol.valLabel.textContent = formatMin(+hCol.slider.value); updateGapReadout(); };

  const submitBtn = html`&lt;button style="padding:8px 20px;border-radius:4px;border:1px solid #5c9e95;background:#5c9e95;color:white;cursor:pointer;font-size:0.95rem;margin-top:8px;"&gt;Comprobar&lt;/button&gt;`;

  card.appendChild(group);
