    card.appendChild(fbBox);
    card.appendChild(contextHoursBarsSvg(data.hoursM, data.hoursH));
    card.appendChild(retryButton(container, buildThermoDurationDemo));
  };
}







function buildRaceDurationDemo(container) {
  const ageTab = randomAgeTab();
  const data = roundData(ageTab);
  const GMAX = 150;

  const card = html`&lt;div style="max-width: 640px; margin: 0 auto; padding: 24px; border-radius: 10px; background: color-mix(in srgb, currentColor 5%, transparent); text-align:center;"&gt;&lt;/div&gt;`;
  const group = html`&lt;div style="font-weight: 700; font-size: 1.1rem; margin-bottom: 8px;"&gt;${ageTabLabel[ageTab]}&lt;/div&gt;`;
  const question = html`&lt;div style="margin-bottom: 16px; max-width: 480px; margin-left:auto; margin-right:auto;"&gt;Apuesta cuántos &lt;strong&gt;minutos más&lt;/strong&gt; sigue corriendo el cronómetro de las &lt;span style="color:${colorM}; font-weight:700;"&gt;mujeres&lt;/span&gt; después de que se detiene el de los &lt;span style="color:${colorH}; font-weight:700;"&gt;hombres&lt;/span&gt; — luego dale a correr y mira quién llega primero.&lt;/div&gt;`;

  let guessVal = 0;
  const readout = html`&lt;div style="font-size: 1.1rem; font-weight: 700; margin-bottom: 8px;"&gt;${formatMin(0)}&lt;/div&gt;`;
  const slider = html`&lt;input type="range" min="0" max="${GMAX}" step="5" value="0" style="width: 100%; max-width: 420px;"&gt;`;
  slider.oninput = () =&gt; { guessVal = +slider.value; readout.textContent = formatMin(guessVal); };

  function stopwatchRow(label, color) {
    const row = html`&lt;div style="display:flex; align-items:center; gap:12px; margin-bottom: 10px;"&gt;&lt;/div&gt;`;
    const nameTag = html`&lt;div style="width:70px; text-align:left; font-weight:700; color:${color};"&gt;${label}&lt;/div&gt;`;
    const track = html`&lt;div style="flex:1; height:16px; background:color-mix(in srgb, currentColor 10%, transparent); border-radius:8px; overflow:hidden;"&gt;&lt;/div&gt;`;
    const fill = html`&lt;div style="height:100%; width:0%; background:${color}; border-radius:8px;"&gt;&lt;/div&gt;`;
    track.appendChild(fill);
    const timeLabel = html`&lt;div style="width:110px; text-align:right; font-variant-numeric: tabular-nums; font-weight:700;"&gt;0 min&lt;/div&gt;`;
    row.appendChild(nameTag);
    row.appendChild(track);
    row.appendChild(timeLabel);
    return { row, fill, timeLabel };
  }

  const raceHolder = html`&lt;div style="max-width: 480px; margin: 0 auto 12px;"&gt;&lt;/div&gt;`;
  const mRow = stopwatchRow("Mujeres", colorM);
  const hRow = stopwatchRow("Hombres", colorH);
  raceHolder.appendChild(mRow.row);
  raceHolder.appendChild(hRow.row);

  const startBtn = html`&lt;button style="padding:8px 20px;border-radius:4px;border:1px solid #5c9e95;background:#5c9e95;color:white;cursor:pointer;font-size:0.95rem;margin-top:8px;"&gt;Iniciar carrera ▶&lt;/button&gt;`;

  card.appendChild(group);
  card.appendChild(question);
  card.appendChild(readout);
  card.appendChild(slider);
  card.appendChild(raceHolder);
  card.appendChild(startBtn);
  container.appendChild(card);

  startBtn.onclick = () =&gt; {
    slider.disabled = true;
    startBtn.disabled = true;
    startBtn.textContent = "Corriendo...";

    const totalM = data.hoursM * 60, totalH = data.hoursH * 60;
    const maxTotal = Math.max(totalM, totalH);
    const DURATION_MS = 3200;
    const rate = maxTotal / DURATION_MS;
    const t0 = performance.now();
    let hFlagged = false;

    function frame(now) {
      const elapsed = now - t0;
      const simMin = Math.min(elapsed * rate, maxTotal);
      const mVal = Math.min(simMin, totalM);
      const hVal = Math.min(simMin, totalH);
      mRow.fill.style.width = (mVal / maxTotal * 100) + "%";
      hRow.fill.style.width = (hVal / maxTotal * 100) + "%";
      mRow.timeLabel.textContent = formatMin(Math.round(mVal));
      if (hVal &gt;= totalH && !hFlagged) { hFlagged = true; }
      hRow.timeLabel.textContent = formatMin(Math.round(hVal)) + (hFlagged ? " 🏁" : "");
      if (simMin &lt; maxTotal) {
        requestAnimationFrame(frame);
      } else {
        finish();
      }
    }
    requestAnimationFrame(frame);

    function finish() {
      startBtn.remove();
      const errorAbs = Math.abs(guessVal - data.gapMin);
      const fb = feedback(errorAbs, data.gapMin);
      const fbBox = html`&lt;div style="font-size: 1.05rem; margin: 16px 0;"&gt;&lt;span style="font-size:1.4rem;"&gt;${fb.emoji}&lt;/span&gt; ${fb.text} Apostaste &lt;strong&gt;${formatMin(guessVal)}&lt;/strong&gt;, la diferencia real es &lt;strong&gt;${formatMin(data.gapMin)}&lt;/strong&gt; (te desviaste por ${formatMin(errorAbs)}).&lt;/div&gt;`;
      card.appendChild(fbBox);
      card.appendChild(contextHoursBarsSvg(data.hoursM, data.hoursH));
      card.appendChild(retryButton(container, buildRaceDurationDemo));
    }
  };
}







